 total=sum(lines.values());cont=total*D('1.25');tax=cont*D('1.16');mxn=tax*D('20.50')*D('1.10')
 cases[name]={'hours':str(h),'linesUsd':{k:str(v.quantize(D('.0001'))) for k,v in lines.items()},'grossUsd':str(total.quantize(D('.01'))),'with25PercentUsd':str(cont.quantize(D('.01'))),'illustrative16PercentTaxUsd':str(tax.quantize(D('.01'))),'illustrativeMxnAt20_50With10PercentFxRisk':str(mxn.quantize(D('.01'))),'within20UsdBeforeTax':cont<=20,'within20UsdIllustrativeTax':tax<=20,'stressUsdWithTaxLagAndRetention':str((tax+D('2.00')).quantize(D('.01'))),'within20UsdStress':tax+D('2.00')<=20,'authorized':False}
